function atmosphere(){const x=view.w*.57,y=view.h*.26,r=Math.min(view.w,view.h)*.23,g=ctx.createRadialGradient(x,y,r*.1,x,y,r);g.addColorStop(0,artIndex===2?'#f8d6c245':artIndex===1?'#edc7a02d':'#e4dba831');g.addColorStop(1,'#ffe7b000');ctx.fillStyle=g;ctx.fillRect(0,0,view.w,view.h);ctx.save();ctx.globalAlpha=.1;ctx.fillStyle=artIndex===2?'#f2d2c0':artIndex===1?'#e7c6a2':'#d9d7a0';ctx.beginPath();ctx.arc(x,y,r*.46,0,Math.PI*2);ctx.fill();ctx.restore()}

// The final walkable landing is sheltered by an open-book reading pavilion.
function destination(t){const h=elevation(9,9),zs=view.zscale,pt=(u,v,z)=>point(9+u,9+v,h+z*zs),p=project(9,9),cover=artIndex===2?'#d39480':artIndex===1?'#b56656':'#bf6c55';ctx.save();let glow=ctx.createRadialGradient(p.x,p.y,1,p.x,p.y,view.tw*.85);glow.addColorStop(0,'#ffe2a04c');glow.addColorStop(1,'#ffe2a000');ctx.fillStyle=glow;ctx.beginPath();ctx.ellipse(p.x,p.y,view.tw*.65,view.th*.6,0,0,Math.PI*2);ctx.fill();const col=(u)=>{poly([pt(u-.075,0,0),pt(u+.075,0,0),pt(u+.075,0,82),pt(u-.075,0,82)],material('#ead4af',pt(u,0,82)[1],pt(u,0,0)[1],.2));poly([pt(u+.075,0,0),pt(u+.075,.14,0),pt(u+.075,.14,82),pt(u+.075,0,82)],'#a99075');poly([pt(u-.14,-.05,80),pt(u+.14,-.05,80),pt(u+.14,.18,80),pt(u-.14,.18,80)],'#f0ddb8')};col(-.47);col(.47);poly([pt(-.58,-.08,82),pt(.58,-.08,82),pt(.58,.2,82),pt(-.58,.2,82)],cover);poly([pt(-.58,.2,82),pt(.58,.2,82),pt(.58,.2,75),pt(-.58,.2,75)],'#9f6d59');const spineA=pt(0,-.65,84),spineB=pt(0,.65,84),leftA=pt(-.75,-.65,101),leftB=pt(-.75,.65,101),rightA=pt(.75,-.65,101),rightB=pt(.75,.65,101);poly([leftA,spineA,spineB,leftB],material('#fff0ce',leftA[1],spineB[1],.06));poly([spineA,rightA,rightB,spineB],material('#e8d5ad',rightA[1],spineB[1],.12));poly([leftB,spineB,pt(0,.65,79),pt(-.75,.65,96)],cover);poly([spineB,rightB,pt(.75,.65,96),pt(0,.65,79)],'#ad6956');ctx.strokeStyle='#d6af72';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(...spineA);ctx.lineTo(...spineB);ctx.stroke();ctx.strokeStyle='#b39e754f';ctx.lineWidth=.7;for(let u of [-.62,-.45,-.28,.28,.45,.62]){const z=84+Math.abs(u)/.75*17;ctx.beginPath();ctx.moveTo(...pt(u,-.52,z+.2));ctx.lineTo(...pt(u,.52,z+.2));ctx.stroke()}poly([pt(-.08,.65,81),pt(.08,.65,81),pt(.08,.74,60),pt(0,.74,65),pt(-.08,.74,60)],'#ce795a');ctx.restore()}

function libraryWindows(){const h=150*view.zscale;for(let y of[1.22,2.65]){const pt=(v,z)=>point(6.54,y+v,z);poly([pt(-.28,h*.61),pt(.28,h*.61),pt(.28,h*.28),pt(-.28,h*.28)],'#24404b70');for(let [v,color]of [[-.17,'#d7b786'],[0,'#bda278'],[.17,'#d08a72']]){ctx.strokeStyle=color;ctx.lineWidth=Math.max(1,view.tw/26);ctx.beginPath();ctx.moveTo(...pt(v,h*.32));ctx.lineTo(...pt(v,h*.53));ctx.stroke()}ctx.strokeStyle='#e2c9a58a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(...pt(-.32,h*.27));ctx.lineTo(...pt(.32,h*.27));ctx.stroke()}}

function questionOptions(c){let state=(seed^Math.imul(round,2654435761))>>>0;for(let ch of c.id)state=(Math.imul(state,31)+ch.charCodeAt(0))>>>0;const rand=()=>{if(mode!=='endless')return Math.random();state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296};let list=c.options.map((option,i)=>({option,i}));for(let i=list.length-1;i>0;i--){let j=Math.floor(rand()*(i+1));[list[i],list[j]]=[list[j],list[i]]}return list}

function mazeDirections(rand){let dirs=[[2,0],[-2,0],[0,2],[0,-2]];for(let i=dirs.length-1;i>0;i--){let j=Math.floor(rand()*(i+1));[dirs[i],dirs[j]]=[dirs[j],dirs[i]]}return dirs}

function fitScene(){const mobile=(window.innerWidth||view.w)<=700,top=mobile?100:75,bottom=view.h-(mobile?85:60);function bounds(){let min=Infinity,max=-Infinity;for(let y=0;y<11;y++)for(let x=0;x<11;x++)if(grid[y][x]){let p=project(x,y);min=Math.min(min,p.y-view.tw*.6);max=Math.max(max,p.y+elevation(x,y)+14)}for(let u of[-.75,.75])for(let v of[-.65,.65])min=Math.min(min,point(9+u,9+v,elevation(9,9)+101*view.zscale)[1]);return{min,max}}view.oy=0;let b=bounds(),scale=Math.min(1,Math.max(120,bottom-top)/(b.max-b.min));view.tw*=scale;view.th*=scale;view.zscale*=scale;b=bounds();view.oy=top-b.min+Math.max(0,(bottom-top-(b.max-b.min))/2)}
